create table dim_deposito (deposito_id integer primary key, nombre text, zona text);
create table dim_fecha (fecha_id integer primary key, fecha text, semana text, dia_semana text);
create table hecho_entrega (
  entrega_id        integer primary key,
  fecha_id          integer references dim_fecha,
  deposito_id       integer references dim_deposito,
  paquetes          integer,   -- cuántos paquetes tenía la ruta ese día
  entregado_a_tiempo integer,  -- cuántos llegaron dentro de la ventana prometida
  completo          integer    -- cuántos llegaron sin faltantes
);

// Datos INVENTADOS: unidades (en miles) de ventiladores de una distribuidora ficticia.
const meses = ["Ene", "Feb", "Mar", "Abr", "May", "Jun"];
const pronostico = [100, 105, 120, 150, 190, 140];   // lo que Comercial espera vender
const abastecimiento = [130, 130, 130, 130, 130, 130]; // lo que el proveedor puede entregar por mes

function simular(nombre, plan, stockInicial) {
  let stock = stockInicial;
  let faltante = 0;
  console.log("== " + nombre + " (stock inicial " + stockInicial + ") ==");
  console.log("mes  demanda  llega  stock_final  faltante");
  meses.forEach((m, i) => {
    stock += plan[i] - pronostico[i];
    let f = 0;
    if (stock < 0) { f = -stock; stock = 0; }
    faltante += f;
    console.log(m.padEnd(4), String(pronostico[i]).padStart(7), String(plan[i]).padStart(6), String(stock).padStart(11), String(f).padStart(9));
  });
  console.log("Faltante total:", faltante, "\n");
}

simular("Plan A: el proveedor entrega parejo", abastecimiento, 20);
// Plan B: se negocia con el proveedor 140 en feb y mar (adelantar compras antes del pico)
simular("Plan B: 140 en feb y mar", [130, 140, 140, 130, 130, 130], 20);

